    }
    // Already completed guidance does not need replay after native compaction.
    for (const g of s.guides.values()) if (g.saved && g.saved === g.prepared) snapshot.set(g.id, g.saved)
    s.snapshots.set(candidates[0].info.id, snapshot)
    if (s.snapshots.size > 128) s.snapshots.delete(s.snapshots.keys().next().value!)
    s.fallback = false; s.active = true
    if (s.permit && this.version(s) !== s.permit.version) this.invalidate(s)
  }
  async gate(input: { tool: string; sessionID: string; callID: string }) {
    if (input.tool === "steering_status") return
    const s = this.state(input.sessionID)
    if (!s.guides.size) return
    if (s.native.has(input.callID) && input.tool === "task") { this.diagnostic(s, "native subtask exempt"); return }
    if ((!s.calls.has(input.callID) || [...s.guides.values()].some(g => g.dirty)) && !s.fallback) {
      s.fallback = true
      try { await this.history(s) } catch { this.diagnostic(s, "gate history unavailable") }
    }
    if (input.tool === "task" && (s.native.has(input.callID) || !s.calls.has(input.callID))) {
      this.diagnostic(s, "native or unknown task exempt to avoid uncaught native hook failure"); return
    }
    const snapshot = s.snapshots.get(s.calls.get(input.callID) ?? "")
    const stale = this.ordered(s).filter(g => !g.saved || g.dirty || snapshot?.get(g.id) !== g.saved)
    if (!stale.length) return
    this.toast(s, "Skipped an obsolete tool; latest guidance will be used next")
    this.diagnostic(s, `blocked ${input.tool} ${input.callID}`)
    throw new Error(`STEERING_STALE_CONTEXT: request did not prepare latest guidance (${stale.map(g => g.id).join(", ")}). ${reminder}`)
  }
  compact(id: string) { const s = this.state(id); this.invalidate(s, true); s.compacting = true; s.calls.clear(); s.native.clear() }
  private schedule(s: State) {
    if (this.options.autoResume === false || s.active || s.stopped || s.timer || s.permit || !this.pending(s).length) return
    s.timer = setTimeout(() => {
      s.timer = undefined
      void this.resume(s).catch(() => this.diagnostic(s, "recovery failed; retry manually"))
    }, 75)
    s.timer.unref?.()
  }
  private valid(s: State, p: Permit) { return s.permit === p && s.epoch === p.epoch && !s.stopped && this.version(s) === p.version }
  private async resume(s: State) {
    const epoch = s.epoch
    const messages = await this.history(s)
    if (epoch !== s.epoch || s.stopped || s.active || !this.pending(s).length) return
    const latest = [...messages].reverse().find(m => m.info.role === "assistant" && !m.info.summary)
    if (!latest || latest.info.error || !latest.info.time?.completed || !latest.info.finish ||
      ["tool-calls", "unknown", "error"].includes(latest.info.finish) && !latest.info.structured) return
    const version = this.version(s)
    if (s.attempts.some(p => p.version === version)) return
    const unattempted = this.pending(s).filter(g => g.attempted !== g.saved)
    if (!unattempted.length) return
    const g = this.ordered(s).filter(g => g.saved && !g.dirty).at(-1)!
    const info = g.info
    if (typeof info.agent !== "string" || !info.model || typeof info.model !== "object" ||
      typeof (info.model as { providerID?: unknown }).providerID !== "string" ||
      typeof (info.model as { modelID?: unknown }).modelID !== "string" ||
      info.system !== undefined && typeof info.system !== "string" || info.variant !== undefined && typeof info.variant !== "string" ||
      info.format !== undefined && (!info.format || typeof info.format !== "object")) {
      this.diagnostic(s, "cannot safely inherit guidance request fields"); return
    }
    const p: Permit = { key: randomUUID(), epoch, version, assistant: latest.info.id, status: "reserved" }
    s.permit = p; s.attempts.push(p)
    for (const guide of unattempted) guide.attempted = guide.saved
    if (s.attempts.length > 256) { s.stopped = true; this.diagnostic(s, "recovery attempt capacity reached"); return }
    try {
      const status = await this.input.client.session.status({ query: { directory: this.input.directory }, signal: AbortSignal.timeout(1500) })
      if (!this.valid(s, p)) return
      const session = await this.input.client.session.get(this.params(s))
      if (!this.valid(s, p)) return
      if (status.error || !status.data || status.data[s.id]?.type && status.data[s.id].type !== "idle" || session.error || !session.data || session.data.revert) {
        this.invalidate(s, true); this.diagnostic(s, "recovery suppressed by status/revert check"); return
      }
      // Local narrow adaptation: SDK v1 omits synthetic/metadata/variant/format,
      // all accepted by the pinned public runtime prompt schema.
      const body = { agent: info.agent, model: structuredClone(info.model),
        ...(info.system !== undefined ? { system: info.system } : {}),
        ...(info.variant !== undefined ? { variant: info.variant } : {}),
        ...(info.format !== undefined ? { format: structuredClone(info.format) } : {}),
        parts: [{ type: "text", synthetic: true, text: "[Steering continuation] Re-read original saved guidance " + this.pending(s).map(g => g.id).join(", ") + ". " + reminder,
          metadata: { [marker]: { plugin: "@oneshot/opencode-steering", kind: "continuation", recoveryKey: p.key } } }] }
      p.status = "dispatch-unknown"
      const result = await this.input.client.session.promptAsync({ ...this.params(s), body: body as NonNullable<Parameters<PluginInput["client"]["session"]["promptAsync"]>[0]>["body"] })
      if (result.error) throw new Error("prompt_async failed")
      // 204 acknowledges dispatch only. chat.message confirms the control permit.
      if (this.valid(s, p) && !p.controlID) this.diagnostic(s, "dispatch acknowledged; control save unknown")
      const timer = setTimeout(() => { if (s.permit === p) s.permit = undefined }, 5000); timer.unref?.()
    } catch { if (p.status !== "suppressed") p.status = "dispatch-unknown"; this.diagnostic(s, "recovery outcome unknown; retry manually") }
  }
  private async control(s: State, key: unknown, id: string) {
    const p = s.permit
    let valid = !!p && p.key === key && this.valid(s, p)
    if (valid) {
      try {
        const session = await this.input.client.session.get(this.params(s))
        valid = !session.error && !!session.data && !session.data.revert && this.valid(s, p!)
        const status = await this.input.client.session.status({ query: { directory: this.input.directory }, signal: AbortSignal.timeout(1500) })
        valid = valid && !status.error && !!status.data && (!status.data[s.id] || status.data[s.id].type === "idle") && this.valid(s, p!)
      } catch { valid = false }
    }
    if (!valid) {
      if (p && p.key === key) { p.status = "suppressed"; s.permit = undefined }
      const token = randomUUID(); this.suppressions.add(token)
      const timer = setTimeout(() => this.suppressions.delete(token), 30000); timer.unref?.()
      throw new Error(`STEERING_RECOVERY_SUPPRESSED (${token})`)
    }
    p!.controlID = id; p!.status = "control-accepted"
    this.toast(s, "Continuing with saved guidance")
  }
  status(id: string) {
    const s = this.sessions.get(id)
    if (!s) return { sessionID: id, evidence: "no observations in this process", provider: "unknown", adopted: "unknown" }
    return { sessionID: id, active: s.active, stopped: s.stopped, provider: "unknown", adopted: "unknown",
      messages: this.ordered(s).map(g => ({ messageID: g.id, saved: !!g.saved && !g.dirty, prepared: !!g.saved && g.prepared === g.saved, eligible: g.eligible })),
      recovery: structuredClone(s.attempts), diagnostics: [...s.diagnostics] }
  }
  async event(event: { type: string; properties?: unknown }) {
    // Everything before returning is synchronous: cancellation invalidates any
    // continuation currently waiting on SDK I/O. Streaming deltas never query history.
    try {
      const p = event.properties as { sessionID?: string; messageID?: string; partID?: string; info?: Message["info"] & { revert?: unknown };
        part?: Part & { sessionID?: string; messageID?: string }; status?: { type: string }; error?: { data?: { message?: string } } }
      const id = p?.sessionID ?? p?.part?.sessionID ?? p?.info?.sessionID ?? (event.type.startsWith("session.") ? p?.info?.id : undefined)
      if (!id) return
      const s = this.state(id)
      if (event.type === "session.error") {
        const token = [...this.suppressions].find(t => p.error?.data?.message?.includes(t))
        if (token) { this.suppressions.delete(token); return }
      }
      if (event.type === "session.deleted" || event.type === "session.error" || p.info?.error || event.type === "session.updated" && p.info?.revert) this.invalidate(s, true)
      if (event.type === "session.deleted") { s.guides.clear(); s.snapshots.clear(); s.calls.clear(); s.native.clear(); return }
      if (event.type === "session.compacted") this.compact(id)
      if (event.type === "session.status" && ["busy", "retry"].includes(p.status?.type ?? "")) s.active = true
      if (event.type === "session.idle" || event.type === "session.status" && p.status?.type === "idle") {
        s.active = false; s.calls.clear(); s.native.clear(); this.schedule(s)
      }
      if (event.type === "message.updated" && p.info) {
        if (p.info.role === "assistant" && s.permit && !s.permit.controlID && p.info.id !== s.permit.assistant) this.invalidate(s)
        const g = s.guides.get(p.info.id)
        if (g) { g.info = p.info; g.infoSaved = true; this.confirm(s, g) }
      }
      if (event.type === "message.part.updated" && p.part) {
        this.map(s, p.part)
        const g = s.guides.get(p.part.messageID ?? "")
        if (g && p.part.id) { const version = partVersion(p.part); if (version) g.parts.set(p.part.id, version); else g.parts.delete(p.part.id); s.revision++; this.confirm(s, g) }
      }
      if (event.type === "message.removed" || event.type === "message.part.removed") {
        this.invalidate(s, true)
        const g = s.guides.get(p.messageID ?? "")
        if (g && event.type === "message.removed") { g.removed = true; g.dirty = true; g.verify = true }
        else if (g) {
          g.parts.delete(p.partID ?? ""); g.expected = contentVersion(g.parts); g.dirty = true; g.verify = true
        }
        s.fallback = false
      }
    } catch { /* Fire-and-forget kernel event hooks must never reject. */ }
  }
  private confirm(s: State, g: Guide) {
    if (!g.infoSaved || g.verify) return
    const actual = contentVersion(g.parts)
    if (actual === g.expected) { g.saved = actual; g.dirty = false; this.schedule(s) }
    else if (g.saved) {
      // A part update can be a delayed event for an earlier edit. Only a
      // current public SDK read can establish an edited saved content version.
      this.invalidate(s); g.dirty = true; g.verify = true; s.fallback = false
    }
  }
}

import { BusEvent } from "@/bus/bus-event"
import { Bus } from "@/bus"
import { Session } from "."
import { SessionID, MessageID, PartID } from "./schema"
import { Instance } from "../project/instance"
import { Provider } from "../provider/provider"
import { MessageV2 } from "./message-v2"
import z from "zod"
import { Token } from "../util/token"
import { Log } from "../util/log"
import { SessionProcessor } from "./processor"
import { fn } from "@/util/fn"
import { Agent } from "@/agent/agent"
import { Plugin } from "@/plugin"
import { Config } from "@/config/config"
import { NotFoundError } from "@/storage/db"
import { ModelID, ProviderID } from "@/provider/schema"
import { Effect, Layer, ServiceMap } from "effect"
import { makeRuntime } from "@/effect/run-service"
import { InstanceState } from "@/effect/instance-state"
import { isOverflow as overflow } from "./overflow"

export namespace SessionCompaction {
  const log = Log.create({ service: "session.compaction" })

  export const Event = {
    Compacted: BusEvent.define(
      "session.compacted",
      z.object({
        sessionID: SessionID.zod,
      }),
    ),
  }

  export const PRUNE_MINIMUM = 20_000
  export const PRUNE_PROTECT = 40_000
  const PRUNE_PROTECTED_TOOLS = ["skill"]

  export interface Interface {
    readonly isOverflow: (input: {
      tokens: MessageV2.Assistant["tokens"]
      model: Provider.Model
    }) => Effect.Effect<boolean>
    readonly prune: (input: { sessionID: SessionID }) => Effect.Effect<void>
    readonly process: (input: {
      parentID: MessageID
      messages: MessageV2.WithParts[]
      sessionID: SessionID
      auto: boolean
      overflow?: boolean
    }) => Effect.Effect<"continue" | "stop">
    readonly create: (input: {
      sessionID: SessionID
      agent: string
      model: { providerID: ProviderID; modelID: ModelID }
      auto: boolean
      overflow?: boolean
    }) => Effect.Effect<void>
  }

  export class Service extends ServiceMap.Service<Service, Interface>()("@opencode/SessionCompaction") {}

  export const layer: Layer.Layer<
    Service,
    never,
    | Bus.Service
    | Config.Service
    | Session.Service
    | Agent.Service
    | Plugin.Service
    | SessionProcessor.Service
    | Provider.Service
  > = Layer.effect(
    Service,
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const config = yield* Config.Service
      const session = yield* Session.Service
      const agents = yield* Agent.Service
      const plugin = yield* Plugin.Service
      const processors = yield* SessionProcessor.Service
      const provider = yield* Provider.Service

      const isOverflow = Effect.fn("SessionCompaction.isOverflow")(function* (input: {
        tokens: MessageV2.Assistant["tokens"]
        model: Provider.Model
      }) {
        return overflow({ cfg: yield* config.get(), tokens: input.tokens, model: input.model })
      })

      // goes backwards through parts until there are PRUNE_PROTECT tokens worth of tool
      // calls, then erases output of older tool calls to free context space
      const prune = Effect.fn("SessionCompaction.prune")(function* (input: { sessionID: SessionID }) {
        const cfg = yield* config.get()
        if (cfg.compaction?.prune === false) return
        log.info("pruning")

        const msgs = yield* session
          .messages({ sessionID: input.sessionID })
          .pipe(Effect.catchIf(NotFoundError.isInstance, () => Effect.succeed(undefined)))
        if (!msgs) return

        let total = 0
        let pruned = 0
        const toPrune: MessageV2.ToolPart[] = []
        let turns = 0

        loop: for (let msgIndex = msgs.length - 1; msgIndex >= 0; msgIndex--) {
          const msg = msgs[msgIndex]
          if (msg.info.role === "user") turns++
          if (turns < 2) continue
          if (msg.info.role === "assistant" && msg.info.summary) break loop
          for (let partIndex = msg.parts.length - 1; partIndex >= 0; partIndex--) {
            const part = msg.parts[partIndex]
            if (part.type === "tool")
              if (part.state.status === "completed") {
                if (PRUNE_PROTECTED_TOOLS.includes(part.tool)) continue
                if (part.state.time.compacted) break loop
                const estimate = Token.estimate(part.state.output)
                total += estimate
                if (total > PRUNE_PROTECT) {
                  pruned += estimate
                  toPrune.push(part)
                }
              }
          }
        }

        log.info("found", { pruned, total })
        if (pruned > PRUNE_MINIMUM) {
          for (const part of toPrune) {
            if (part.state.status === "completed") {
              part.state.time.compacted = Date.now()
              yield* session.updatePart(part)
            }
          }
          log.info("pruned", { count: toPrune.length })
        }
      })

      const processCompaction = Effect.fn("SessionCompaction.process")(function* (input: {
        parentID: MessageID
        messages: MessageV2.WithParts[]
        sessionID: SessionID
        auto: boolean
        overflow?: boolean
      }) {
        const parent = input.messages.findLast((m) => m.info.id === input.parentID)
        if (!parent || parent.info.role !== "user") {
          throw new Error(`Compaction parent must be a user message: ${input.parentID}`)
        }
        const userMessage = parent.info

        let messages = input.messages
        let replay:
          | {
              info: MessageV2.User
              parts: MessageV2.Part[]
            }
          | undefined
        if (input.overflow) {
          const idx = input.messages.findIndex((m) => m.info.id === input.parentID)
          for (let i = idx - 1; i >= 0; i--) {
            const msg = input.messages[i]
            if (msg.info.role === "user" && !msg.parts.some((p) => p.type === "compaction")) {
              replay = { info: msg.info, parts: msg.parts }
              messages = input.messages.slice(0, i)
              break
            }
          }
          const hasContent =
            replay && messages.some((m) => m.info.role === "user" && !m.parts.some((p) => p.type === "compaction"))
          if (!hasContent) {
            replay = undefined
            messages = input.messages
          }
        }

        const agent = yield* agents.get("compaction")
        const model = agent.model
          ? yield* provider.getModel(agent.model.providerID, agent.model.modelID)
          : yield* provider.getModel(userMessage.model.providerID, userMessage.model.modelID)
        // Allow plugins to inject context or replace compaction prompt.
        const compacting = yield* plugin.trigger(
          "experimental.session.compacting",
          { sessionID: input.sessionID },
          { context: [], prompt: undefined },
        )
        const defaultPrompt = `Provide a detailed prompt for continuing our conversation above.
Focus on information that would be helpful for continuing the conversation, including what we did, what we're doing, which files we're working on, and what we're going to do next.
The summary that you construct will be used so that another agent can read it and continue the work.
Do not call any tools. Respond only with the summary text.
Respond in the same language as the user's messages in the conversation.

When constructing the summary, try to stick to this template:
---
## Goal

[What goal(s) is the user trying to accomplish?]

## Instructions

- [What important instructions did the user give you that are relevant]
- [If there is a plan or spec, include information about it so next agent can continue using it]

## Discoveries

[What notable things were learned during this conversation that would be useful for the next agent to know when continuing the work]

## Accomplished

[What work has been completed, what work is still in progress, and what work is left?]

## Relevant files / directories

[Construct a structured list of relevant files that have been read, edited, or created that pertain to the task at hand. If all the files in a directory are relevant, include the path to the directory.]
---`

        const prompt = compacting.prompt ?? [defaultPrompt, ...compacting.context].join("\n\n")
        const msgs = structuredClone(messages)
        yield* plugin.trigger("experimental.chat.messages.transform", {}, { messages: msgs })
        const modelMessages = yield* MessageV2.toModelMessagesEffect(msgs, model, { stripMedia: true })
        const ctx = yield* InstanceState.context
        const msg: MessageV2.Assistant = {
          id: MessageID.ascending(),
          role: "assistant",
          parentID: input.parentID,
          sessionID: input.sessionID,
          mode: "compaction",
          agent: "compaction",
          variant: userMessage.variant,
          summary: true,
          path: {
            cwd: ctx.directory,
            root: ctx.worktree,
          },
          cost: 0,
          tokens: {
            output: 0,
            input: 0,
            reasoning: 0,
            cache: { read: 0, write: 0 },
          },
          modelID: model.id,
          providerID: model.providerID,
          time: {
            created: Date.now(),
          },
        }
        yield* session.updateMessage(msg)
        const processor = yield* processors.create({
          assistantMessage: msg,
          sessionID: input.sessionID,
          model,
        })
        const result = yield* processor
          .process({
            user: userMessage,
            agent,
            sessionID: input.sessionID,
            tools: {},
            system: [],
            messages: [
              ...modelMessages,
              {
                role: "user",
                content: [{ type: "text", text: prompt }],
              },
            ],
            model,
          })
          .pipe(Effect.onInterrupt(() => processor.abort()))

        if (result === "compact") {
          processor.message.error = new MessageV2.ContextOverflowError({
            message: replay
              ? "Conversation history too large to compact - exceeds model context limit"
              : "Session too large to compact - context exceeds model limit even after stripping media",
          }).toObject()
          processor.message.finish = "error"
          yield* session.updateMessage(processor.message)
          return "stop"
        }

        if (result === "continue" && input.auto) {
          if (replay) {
            const original = replay.info
            const replayMsg = yield* session.updateMessage({
              id: MessageID.ascending(),
              role: "user",
              sessionID: input.sessionID,
              time: { created: Date.now() },
              agent: original.agent,
              model: original.model,
              format: original.format,
              tools: original.tools,
              system: original.system,
              variant: original.variant,
            })
            for (const part of replay.parts) {
              if (part.type === "compaction") continue
              const replayPart =
                part.type === "file" && MessageV2.isMedia(part.mime)
                  ? { type: "text" as const, text: `[Attached ${part.mime}: ${part.filename ?? "file"}]` }
                  : part
              yield* session.updatePart({
                ...replayPart,
                id: PartID.ascending(),
                messageID: replayMsg.id,
                sessionID: input.sessionID,
              })
            }
          }

          if (!replay) {
            const continueMsg = yield* session.updateMessage({
              id: MessageID.ascending(),
              role: "user",
              sessionID: input.sessionID,
              time: { created: Date.now() },
              agent: userMessage.agent,
              model: userMessage.model,
            })
            const text =
              (input.overflow
                ? "The previous request exceeded the provider's size limit due to large media attachments. The conversation was compacted and media files were removed from context. If the user was asking about attached images or files, explain that the attachments were too large to process and suggest they try again with smaller or fewer files.\n\n"
                : "") +
              "Continue if you have next steps, or stop and ask for clarification if you are unsure how to proceed."
            yield* session.updatePart({
              id: PartID.ascending(),
              messageID: continueMsg.id,
              sessionID: input.sessionID,
              type: "text",
              synthetic: true,
              text,
              time: {
                start: Date.now(),
                end: Date.now(),
              },
            })
          }
        }

        if (processor.message.error) return "stop"
        if (result === "continue") yield* bus.publish(Event.Compacted, { sessionID: input.sessionID })
        return result
      })

      const create = Effect.fn("SessionCompaction.create")(function* (input: {
        sessionID: SessionID
        agent: string
        model: { providerID: ProviderID; modelID: ModelID }
        auto: boolean
        overflow?: boolean
      }) {
        const msg = yield* session.updateMessage({
          id: MessageID.ascending(),
          role: "user",
          model: input.model,
          sessionID: input.sessionID,
          agent: input.agent,
          time: { created: Date.now() },
        })
        yield* session.updatePart({
          id: PartID.ascending(),
          messageID: msg.id,
          sessionID: msg.sessionID,
          type: "compaction",
          auto: input.auto,
          overflow: input.overflow,
        })
      })

      return Service.of({
        isOverflow,
        prune,
        process: processCompaction,
        create,
      })
    }),
  )

  export const defaultLayer = Layer.unwrap(
    Effect.sync(() =>
      layer.pipe(
        Layer.provide(Provider.defaultLayer),
        Layer.provide(Session.defaultLayer),
        Layer.provide(SessionProcessor.defaultLayer),
        Layer.provide(Agent.defaultLayer),
        Layer.provide(Plugin.defaultLayer),
        Layer.provide(Bus.layer),
        Layer.provide(Config.defaultLayer),
      ),
    ),
  )

  const { runPromise } = makeRuntime(Service, defaultLayer)

  export async function isOverflow(input: { tokens: MessageV2.Assistant["tokens"]; model: Provider.Model }) {
    return runPromise((svc) => svc.isOverflow(input))
  }

  export async function prune(input: { sessionID: SessionID }) {
    return runPromise((svc) => svc.prune(input))
  }

  export const process = fn(
    z.object({
      parentID: MessageID.zod,
      messages: z.custom<MessageV2.WithParts[]>(),
      sessionID: SessionID.zod,
      auto: z.boolean(),
      overflow: z.boolean().optional(),
    }),
    (input) => runPromise((svc) => svc.process(input)),
  )

  export const create = fn(
    z.object({
      sessionID: SessionID.zod,
      agent: z.string(),
      model: z.object({ providerID: ProviderID.zod, modelID: ModelID.zod }),
      auto: z.boolean(),
      overflow: z.boolean().optional(),
    }),
    (input) => runPromise((svc) => svc.create(input)),
  )
}
import assert from 'node:assert/strict'
import { test } from 'node:test'
import http from 'node:http'
import { mkdtemp, mkdir, writeFile, access, readFile } from 'node:fs/promises'
import path from 'node:path'
import { setTimeout as delay } from 'node:timers/promises'
import { startKernel, until, finish, root, entry, model } from './kernel.mjs'

async function lab(t, enabled, { barriers = false, dispatchBarrier = false, extra = {} } = {}) {
  const requests = [], held = [], events = [], waits = new Map()
  await mkdir(path.join(root, '.codeagent'), { recursive: true })
  const directory = await mkdtemp(path.join(root, '.codeagent/steering-v2-case-'))
  const server = http.createServer(async (req, res) => {
    let raw = ''; for await (const c of req) raw += c
    if (req.url.startsWith('/barrier/')) { waits.set(req.url.split('/').at(-1), res); return }
    if (req.url === '/event') { events.push(JSON.parse(raw)); res.end('{}'); return }
    requests.push(JSON.parse(raw)); held.push(res)
  })
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
  const provider = `http://127.0.0.1:${server.address().port}`
  const companion = path.join(directory, 'companion.mjs')
  await writeFile(companion, `export default async ctx => {
    if (${dispatchBarrier}) {
      const get = ctx.client.session.get.bind(ctx.client.session); let once = false
      ctx.client.session.get = async args => { if (!once) { once = true; await fetch(${JSON.stringify(provider + "/barrier/dispatch")}) }; return get(args) }
    }
    return ({
    async 'chat.message'(_, out) {
      const text = out.parts.find(p=>p.type==='text'&&!p.synthetic)?.text || ''
      const which = ${barriers} && (text.startsWith('TASK:')?'task':text.startsWith('GUIDE:')?'guide':undefined)
      await fetch(${JSON.stringify(provider + '/event')}, {method:'POST', body:JSON.stringify({kind:'message',which,id:out.message.id,parts:out.parts,info:out.message})})
      if(which) await fetch(${JSON.stringify(provider + '/barrier/')}+which)
    }
  })}`)
  let kernel
  try { kernel = await startKernel({ provider, directory, plugin: [companion, ...(enabled ? [entry] : [])], extra }) }
  catch (e) { server.closeAllConnections(); server.close(); throw e }
  t.after(async () => {
    for (const r of [...held, ...waits.values()]) r.destroy()
    server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); await kernel.stop()
    await writeFile(path.join(directory, 'evidence.json'), JSON.stringify({ source: 'deterministic', enabled, requests, events }, null, 2))
  })
  const session = await kernel.request('/session', { title: 'Steering v2 integration', permission: [{ permission: '*', pattern: '*', action: 'allow' }] })
  const route = '/session/' + session.id
  const submit = (text, fields = {}) => kernel.request(route + '/prompt_async', { model, agent: 'build', parts: [{ type: 'text', text }], ...fields })
  const messages = () => kernel.request(route + '/message')
  const idle = async () => !(await kernel.request('/session/status'))[session.id]
  return { ...kernel, directory, session, route, submit, messages, idle, requests, held, events, waits }
}
async function exists(file) { return access(file).then(() => true, () => false) }

for (const enabled of [false, true]) test(`A2/A4/A5/A10 multiple tools in one assistant; plugin=${enabled}`, { timeout: 60000 }, async t => {
  const f = await lab(t, enabled)
  await f.submit('TASK: write the old files, then finish.')
  await until(() => f.requests.length === 1, 'first provider request')
  await f.submit('CORRECTION_ONE: do not write old files.')
  await until(async () => (await f.messages()).filter(m => m.info.role === 'user').length === 2, 'first guide saved')
  await f.submit('CORRECTION_TWO: newest guidance wins. Preserve completed results.')
  await until(async () => (await f.messages()).filter(m => m.info.role === 'user').length === 3, 'second guide saved')
  const targets = ['old-a.txt', 'old-b.txt'].map(name => path.join(f.directory, name))
  finish(f.held[0], null, targets.map(target => ({ name: 'bash', args: { command: `printf obsolete > '${target}'`, description: 'old action' } })))
  await until(() => f.requests.length >= 2, 'second request')
  const saved = await f.messages(), toolMessages = saved.filter(m => m.parts.some(p => p.type === 'tool'))
  assert.equal(toolMessages.length, 1, 'Both calls belong to the same assistant')
  const parts = toolMessages[0].parts.filter(p => p.type === 'tool')
  assert.equal(parts.length, 2)
  for (const target of targets) assert.equal(await exists(target), !enabled)
  if (enabled) {
    assert.ok(parts.every(p => p.state.status === 'error' && p.state.error.includes('STEERING_STALE_CONTEXT')))
    assert.ok(JSON.stringify(f.requests[1]).includes('Latest user guidance takes priority'))
  } else assert.ok(parts.every(p => p.state.status === 'completed'))
  for (const text of ['CORRECTION_ONE:', 'CORRECTION_TWO:']) assert.ok(JSON.stringify(f.requests[1]).includes(text))
  const newTarget = path.join(f.directory, 'SUMMARY.md')
  finish(f.held[1], null, [{ name: 'bash', args: { command: `printf corrected > '${newTarget}'`, description: 'current action' } }])
  await until(() => f.requests.length >= 3, 'final request')
  assert.equal(await readFile(newTarget, 'utf8'), 'corrected')
  finish(f.held[2]); await until(f.idle, 'idle'); await delay(250)
  assert.equal(f.requests.length, 3, 'No duplicate native continuation')
  assert.equal((await f.messages()).filter(m => m.info.role === 'user').length, 3)
})

for (const enabled of [false, true]) test(`A3 late-save native-ID double barrier; plugin=${enabled}`, { timeout: 60000 }, async t => {
  const f = await lab(t, enabled, { barriers: true })
  await f.submit('TASK: finish original task.')
  await until(() => f.waits.has('task'), 'task ID allocated')
  await f.submit('GUIDE: corrected late-save guidance', { system: 'inherited-system', variant: 'chosen', format: { type: 'text' },
    parts: [{ type: 'text', text: 'GUIDE: corrected late-save guidance' }, { type: 'file', mime: 'text/plain', filename: 'guide.txt', url: 'data:text/plain;base64,YXR0YWNobWVudA==' }] })
  await until(() => f.waits.has('guide'), 'guide ID allocated')
  f.waits.get('task').end('{}'); await until(() => f.requests.length === 1, 'initial request')
  assert.ok(!JSON.stringify(f.requests[0]).includes('GUIDE:'))
  f.waits.get('guide').end('{}')
  let originals, guide
  await until(async () => { originals = await f.messages(); guide = originals.find(m => m.parts.some(p => p.text?.startsWith('GUIDE:'))); return guide?.parts.some(p => p.type === 'file') && guide.parts.some(p => p.text === 'attachment') }, 'all guide parts saved')
  const a = originals.find(m => m.info.role === 'assistant')
  assert.ok(guide.info.id < a.info.id, 'Natural native IDs establish actual late save')
  const permissions = (await f.request(f.route)).permission
  finish(f.held[0])
  if (enabled) {
    await until(() => f.requests.length === 2, 'automatic continuation')
    assert.ok(JSON.stringify(f.requests[1]).includes('GUIDE:'))
    assert.ok(JSON.stringify(f.requests[1]).includes('Latest user guidance takes priority'))
    finish(f.held[1]); await until(f.idle, 'continued idle')
  } else await until(f.idle, 'native stopped without continuation')
  await delay(300)
  assert.equal(f.requests.length, enabled ? 2 : 1)
  const saved = await f.messages(), users = saved.filter(m => m.info.role === 'user')
  assert.equal(users.length, enabled ? 3 : 2)
  assert.deepEqual(users.find(m => m.info.id === guide.info.id).parts, guide.parts)
  assert.deepEqual((await f.request(f.route)).permission, permissions)
  if (enabled) {
    const control = users.find(m => !originals.some(o => o.info.id === m.info.id))
    assert.ok(control.parts.some(p => p.synthetic && p.metadata?.codeagentSteering))
    assert.equal(control.info.system, guide.info.system); assert.equal(control.info.variant, guide.info.variant); assert.deepEqual(control.info.format, guide.info.format)
    assert.ok(!JSON.stringify(control.parts).includes('corrected late-save guidance'))
  }
})

