import type { Plugin } from "@opencode-ai/plugin"
import { bundledGlobalExtensions } from "../../agent-kernel-extension/src/custom-hw/extension/bundled-global-extensions"
import { composeGlobalExtensions } from "../../agent-kernel-extension/src/custom-hw/extension/global-extension"
import { SteeringPlugin } from "../steering/src/index.ts"
import { composeSteeringHooks } from "./steering/compose.ts"

// The pinned kernel has no native GlobalExtension bootstrap. Its public plugin
// loader invokes this bridge, which runs the same bundled registry.
export const CodeAgentPlugin: Plugin = async (input) => composeSteeringHooks(
  await composeGlobalExtensions(bundledGlobalExtensions, input),
  await SteeringPlugin(input),
)
import { CapabilityWatchExtension } from "../../codeagent/capability-watch/capability-watch-extension"
import { OneShotExtension } from "../../codeagent/one-shot/one-shot-extension"
import type { GlobalExtension } from "./global-extension"

export const bundledGlobalExtensions: GlobalExtension[] = [CapabilityWatchExtension, OneShotExtension]
import type { Hooks, PluginInput } from "@opencode-ai/plugin"

export type GlobalExtensionInput = PluginInput

export type GlobalExtension = (input: GlobalExtensionInput) => Promise<Pick<Hooks, "event" | "tool">>

export async function composeGlobalExtensions(extensions: GlobalExtension[], input: GlobalExtensionInput) {
  const hooks: Awaited<ReturnType<GlobalExtension>>[] = []
  for (const extension of extensions) hooks.push(await extension(input))
  const tools: NonNullable<Hooks["tool"]> = {}

  for (const hook of hooks) {
    for (const [name, definition] of Object.entries(hook.tool ?? {})) {
      if (name in tools) throw new Error(`Duplicate global extension tool: ${name}`)
      tools[name] = definition
    }
  }

  return {
    tool: tools,
    event: async (event: Parameters<NonNullable<Hooks["event"]>>[0]) => {
      for (const hook of hooks) await hook.event?.(event)
    },
  } satisfies Pick<Hooks, "event" | "tool">
}

